head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDBNS30000";
scwin.pnl_Search = null;
scwin.btn_Search = null;
scwin.pnl_Item = null;
scwin.grd_List = null;
scwin.vSchClsDd = '';
scwin.processGp = undefined;
scwin.vRowCount = 0;
scwin.vStdCd = undefined;
scwin.vClsApplyYn = undefined;
scwin.vStrtDd = undefined;
scwin.dts_List = null;
scwin.dts_Checker = null;
scwin.dts_CheckerBiz = null;
scwin.dts_Temp = null;
scwin.dts_MktDetail = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.pnl_Search = $c.util.getComponent('pnl_Search');
        scwin.btn_Search = $c.util.getComponent('btn_Search');
        scwin.pnl_Item = $c.util.getComponent('pnl_Item');
        scwin.grd_List = $c.util.getComponent('grd_List');
        scwin.dts_List = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_List')) : $c.util.getComponent('dts_List');
        scwin.dts_Checker = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_Checker')) : $c.util.getComponent('dts_Checker');
        scwin.dts_CheckerBiz = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_CheckerBiz')) : $c.util.getComponent('dts_CheckerBiz');
        scwin.dts_Temp = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_Temp')) : $c.util.getComponent('dts_Temp');
        scwin.dts_MktDetail = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_MktDetail')) : $c.util.getComponent('dts_MktDetail');
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldbns30000.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.btn_Search.hide();
        btn_ReClsProcs.hide();
        if (js_usr_tp_cd === '1') {
            btn_ReClsProcs.show("");
        }
        img_ClsDd.hide();
        txt_lbl_SendTm.hide();
        ipt_txb_SendTm.hide();
        BnsPanelToGroupBox(scwin.pnl_Search);
        BnsPanelToGroupBox(scwin.pnl_Item);
        scwin.processGp = '1';
        scwin.searchClsCheck();
        (scwin.dts_Temp && typeof scwin.dts_Temp.setDataHeader === "function" && scwin.dts_Temp.setDataHeader('TEMP:String'));
        (scwin.dts_Temp.insertRow(), scwin.dts_Temp.setRowPosition(scwin.dts_Temp.getRowCount()-1));

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbns30000.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description btn_Search 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = function () {
    try {
        scwin.processGp = '2';
        scwin.vSchClsDd = cal_edt_ClsDd.getValue();
        scwin.searchClsEnd();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbns30000.btn_Search_onclick' }); }
};

/**
 * @method
 * @name dts_List_onloaderror
 * @description 알림을 띄운다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_onloaderror = async function () {
    try {
        await $c.win.alert($c.data.getMessage("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldbns30000.dts_List_onloaderror" });
    }
};

/**
 * @method
 * @name dts_List_onloadcompleted
 * @description dts_List onloadcompleted 이벤트
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_onloadcompleted = function (rowcount) {
    try {
        scwin.vRowCount = rowcount;
        void 0;
        if (rowcount > 0 && scwin.processGp === '2') {
            ipt_txb_UseNm.setValue(scwin.dts_List.getCellData(1, 'USR_NM'));
            ipt_txb_TaskTm.setValue(scwin.dts_List.getCellData(1, 'TASK_TM'));
            ipt_txb_ClsProcsYn.setValue(scwin.dts_List.getCellData(1, 'CLS_PROCS_YN'));
            ipt_txb_SendTm.setValue(scwin.dts_List.getCellData(1, 'SND_CLS_TM'));
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldbns30000.dts_List_onloadcompleted" });
    }
};

/**
 * @method
 * @name trs_Save_onfail
 * @description 알림을 띄운다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_onfail = async function () {
    try {
        await $c.win.alert($c.data.getMessage("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldbns30000.trs_Save_onfail" });
    }
};

/**
 * @method
 * @name trs_Save_onsuccess
 * @description 알림을 띄운다 외
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_onsuccess = async function () {
    try {
        await $c.win.alert($c.data.getMessage("MSG-0001"));
        scwin.processGp = '1';
        scwin.searchClsCheck();
        scwin.searchCls();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldbns30000.trs_Save_onsuccess" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description btn_Excel 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function () {
    try {
        if (scwin.dts_List.CountRow === 0) {
            return;
        }
        const fileNm = $c.session.getExcelDownPath() + $c.date.formatDate("yyyymmddhhmmss") + "_국고(이표)채정보송신마감.xls";
        scwin.grd_List.GridToExcel("국고(이표)채정보송신마감", "", 8);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbns30000.btn_Excel_onclick' }); }
};

/**
 * @method
 * @name btn_ClsProcs_onclick
 * @description 「[없음]」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_ClsProcs_onclick = async function () {
    try {
        await scwin.sbm_trs_Save();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbns30000.btn_ClsProcs_onclick' }); }
};

/**
 * @method
 * @name dts_Checker_onloadcompleted
 * @description dts_Checker onloadcompleted 이벤트
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Checker_onloadcompleted = function (rowcount) {
    try {
        if (scwin.processGp === '4') {
            return;
        }
        cal_edt_ClsDd.setValue(scwin.dts_Checker.getCellData(1, "CUR_DD"));
        ipt_txb_ClsProcsYn.setValue(scwin.dts_Checker.getCellData(1, "CLS_PROCS_YN"));
        ipt_txb_UseNm.setValue(scwin.dts_Checker.getCellData(1, "USR_NM"));
        ipt_txb_TaskTm.setValue(scwin.dts_Checker.getCellData(1, "TASK_TM"));
        if (ipt_txb_ClsProcsYn.getValue() === 'Y') {
            $c.util.getComponent('btn_ClsProcs').setSrc("../img/btn_ClsPrc_d.gif");
            $c.util.getComponent('btn_ClsProcs').setDisabled(true);
        }
        scwin.searchCls();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldbns30000.dts_Checker_onloadcompleted" });
    }
};

/**
 * @method
 * @name tab_List_onselchanged
 * @description tab_List onselchanged 이벤트
 * @param {*} nIndex nIndex
 * @returns {void}
 * @hidden N
 */
scwin.tab_List_onselchanged = function (nIndex) {
    try {
        scwin.dts_List.setValue("");
        scwin.processGp = nIndex;
        ipt_txb_ClsProcsYn.setValue('');
        ipt_txb_UseNm.setValue('');
        ipt_txb_TaskTm.setValue('');
        ipt_txb_SendTm.setValue('');
        if (scwin.processGp === '1') {
            txt_lbl_SendTm.hide();
            ipt_txb_SendTm.hide();
            btn_ClsProcs.show("");
            scwin.btn_Search.hide();
            img_ClsDd.hide();
            $c.util.getComponent('cal_edt_ClsDd').setDisabled(!(false));
            scwin.searchClsCheck();
            btn_TresrybndClsIns.show("");
        } else {
            txt_lbl_SendTm.show("");
            ipt_txb_SendTm.show("");
            if (scwin.vSchClsDd !== '') {
                cal_edt_ClsDd.setValue(scwin.vSchClsDd);
            }
            btn_ClsProcs.hide();
            scwin.btn_Search.show("");
            img_ClsDd.show("");
            $c.util.getComponent('cal_edt_ClsDd').setDisabled(!(true));
            btn_TresrybndClsIns.hide();
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbns30000.tab_List_onselchanged' }); }
};

/**
 * @method
 * @name btn_ReClsProcs_onclick
 * @description 「[없음]」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ReClsProcs_onclick = async function () {
    try {
        await scwin.reClsProcs();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbns30000.btn_ReClsProcs_onclick' }); }
};

/**
 * @method
 * @name btn_TresrybndClsIns_onclick
 * @description 「[없음]」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_TresrybndClsIns_onclick = async function () {
    try {
        await scwin.processTresrybndSendCfm();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbns30000.btn_TresrybndClsIns_onclick' }); }
};

/**
 * @method
 * @name grd_List_onclick
 * @description grd_List 클릭 이벤트
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_onclick = function (row, colid) {
    try {
        if (row === 0) {
            return;
        }
        if (scwin.processGp === '1') {
            scwin.dts_MktDetail.setValue("");
            scwin.vStdCd = scwin.dts_List.getCellData(row, 'STD_CD');
            scwin.searchMktact();
        } else {
            if (scwin.processGp === '2') {
                scwin.dts_MktDetail.setValue("");
                scwin.vStdCd = scwin.dts_List.getCellData(row, 'STD_CD');
                scwin.vClsApplyYn = scwin.dts_List.getCellData(row, 'CLS_APPLY_YN');
                scwin.vStrtDd = scwin.dts_List.getCellData(row, 'STRT_DD');
                scwin.searchMktact1();
            }
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbns30000.grd_List_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name sbm_trs_Save
 * @description trs Save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.sbm_trs_Save = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — sbm_trs_Save"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — sbm_trs_Save", unresolved: "action:self_submit:sbm_trs_Save" };
};

/**
 * @method
 * @name searchClsEnd
 * @description search Cls End 처리
 * @returns {void}
 * @hidden N
 */
scwin.searchClsEnd = function () {
    let param = '';
    param += '&{P}V_CLS_DD=' + cal_edt_ClsDd.getValue();
    const dsNm = 'BNS_CLS_TRESRYBND';
    const qryId = 'lds.stf.bnscls.select.listTresrybndClsEnd';
    fn_SearchBns("ULDBNS30000.gfm", scwin.dts_List, dsNm, qryId, param);  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_SearchBns — as-is 공통(폼 전역 의존) — 반입 보류
    void 0;
};

/**
 * @method
 * @name searchCls
 * @description search Cls 처리
 * @returns {void}
 * @hidden N
 */
scwin.searchCls = function () {
    let param = '';
    param += '&{P}V_GOVBND_FUT_TRNSM_TASK_DD=' + cal_edt_ClsDd.getValue();
    const dsNm = 'BNS_CLS_TRESRYBND';
    const qryId = 'lds.stf.bnstresry.select.createTresrybndAsTaskDd.SendCfm';
    fn_SearchBns("ULDBNS30000.gfm", scwin.dts_List, dsNm, qryId, param);  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_SearchBns — as-is 공통(폼 전역 의존) — 반입 보류
    void 0;
};

/**
 * @method
 * @name searchClsCheck
 * @description search Cls Check 처리
 * @returns {void}
 * @hidden N
 */
scwin.searchClsCheck = function () {
    const dsNm = 'BNS_CLS_TRESRYBND_CHK';
    const qryId = 'lds.stf.bnscls.select.readCheckTresrybndCls';
    fn_SearchBns("ULDBNS30000.gfm", scwin.dts_Checker, dsNm, qryId, '');  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_SearchBns — as-is 공통(폼 전역 의존) — 반입 보류
};

/**
 * @method
 * @name reClsProcs
 * @description re Cls Procs 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.reClsProcs = async function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.lc.fn_encodeNSession
    scwin.processGp = '9';
    const strtDd = scwin.dts_Checker.getCellData(1, 'STRT_DD');
    let msg = '';
    if (scwin.dts_Checker.getCellData(1, 'CLS_PROCS_YN') === 'Y') {
        msg += '채권송신(국고채선물)데이터를 다시 생성하여 송신 할 경우에 해당합니다.';
        msg += '\n다음데이타를 클리어한다.';
        msg += '\n- 국고채전송관리테이블 TBLD_B_GOVBND_FUT_TRNSM 오늘날짜 데이터 삭제, 초기화.';
        await $c.win.alert(msg);
    } else {
        msg += '업무마감이 되지 않아 업무마감처리를';
        msg += '\n다시 하실수 없습니다.';
        await $c.win.alert(msg);
        return;
    }
    if (!await $c.win.confirm($c.data.getMessage("MSG-A006", "재마감처리"))) {
        return;
    }
    let url = "/bns/TresrybndCls.do?method=reProcessCls";
    url += "&SCREN_ID=" + "ULDBNS30000.gfm";
    url += "&SCREN_PROCES_TP_CD=" + $c.fil.SCREN_PROCS_TP_CD_02;
    let param = "STRT_DD=" + strtDd;
    param += ',GOVBND_FUT_TRNSM_TASK_DD=' + cal_edt_ClsDd.getValue();
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Temp)";
    trs_Save.Parameters = param;
    trs_Save.Post();
};

/**
 * @method
 * @name processTresrybndSendCfm
 * @description process Tresrybnd Send Cfm 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.processTresrybndSendCfm = async function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.lc.fn_encodeNSession
    if (scwin.dts_Checker.getCellData(1, 'CLS_PROCS_YN') === 'Y') {
        await $c.win.alert('국고채 업무마감 작업이 이미 종료되었습니다.\n국고채 업무마감 이후에는 전송내역확인 처리를 하실수 없습니다.');
        return;
    }
    if (!await $c.win.confirm($c.data.getMessage("MSG-A006", "국고채 전송내역확인"))) {
        return;
    }
    let url = "/bns/TresrybndCls.do?method=processTresrybndSendCfm";
    url += "&SCREN_ID=" + "ULDBNS30000.gfm";
    url += "&SCREN_PROCES_TP_CD=" + $c.fil.SCREN_PROCS_TP_CD_02;
    const strtDd = scwin.dts_Checker.getCellData(1, 'STRT_DD');
    let param = "STRT_DD=" + strtDd;
    param += ',GOVBND_FUT_TRNSM_TASK_DD=' + cal_edt_ClsDd.getValue();
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Temp)";
    trs_Save.Parameters = param;
    trs_Save.Post();
};

/**
 * @method
 * @name searchMktact
 * @description search Mktact 처리
 * @returns {void}
 * @hidden N
 */
scwin.searchMktact = function () {
    const strtDd = scwin.dts_Checker.getCellData(1, 'STRT_DD');
    let param = '';
    param += "&{P}V_STD_CD=" + scwin.vStdCd;
    param += "&{P}V_STRT_DD=" + strtDd;
    param += "&{P}V_APPL_YN=N";
    const dsNm = 'BNS_MKTACT_DTL';
    const qryId = 'lds.stf.bnscommon.select.listMktactDtlMulty';
    fn_SearchBns("ULDBNS30000.gfm", scwin.dts_MktDetail, dsNm, qryId, param);  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_SearchBns — as-is 공통(폼 전역 의존) — 반입 보류
};

/**
 * @method
 * @name searchMktact1
 * @description search Mktact1 처리
 * @returns {void}
 * @hidden N
 */
scwin.searchMktact1 = function () {
    let param = '';
    param += "&{P}V_STD_CD=" + scwin.vStdCd;
    param += "&{P}V_STRT_DD=" + scwin.vStrtDd;
    const dsNm = 'BNS_MKTACT_DTL';
    const qryId = 'lds.stf.bnscommon.select.listMktactDtlMulty';
    if (scwin.vClsApplyYn === 'Y') {
        param += "&{P}V_APPL_YN=Y";
    } else {
        param += "&{P}V_APPL_YN=N";
    }
    fn_SearchBns("ULDBNS30000.gfm", scwin.dts_MktDetail, dsNm, qryId, param);  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_SearchBns — as-is 공통(폼 전역 의존) — 반입 보류
};
// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
